//! The category D rule table (docs/caraxes/gsp-plan/d-device-model.md §2, roadmap R0): the
//! controls that need device modelling get the plan's labelled answer instead of the
//! dispatcher's `unanswered`.
//!
//! The table is driver-version data (D14): `src/ver/v<major>/dmodel.rs`, generated by
//! caraxes/tools/gsp-dtable.py from docs/caraxes/gsp-plan/d-controls.tsv and the tree's
//! inventory, one rule per control ([`crate::ver::DRule`]). This module answers the rows
//! that stay in D and have a generic answer:
//!
//! * `REFUSE`: the status the header names (NV_ERR_NOT_SUPPORTED unless the row says
//!   otherwise), request echoed, label [`REFUSED`];
//! * `DENY`: refused for isolation, the status the plan names (NV_ERR_INSUFFICIENT_PERMISSIONS
//!   for the host-global scheduler knobs, the DRAM setters and the profiler permission
//!   controls, NV_ERR_NOT_SUPPORTED otherwise), label [`DENIED`];
//! * `ACK`: NV_OK, request echoed, label [`ACKNOWLEDGED`].
//!
//! Not here: the rows that move to E (feature families, chipctl.rs and `[features]` of the
//! chip file), to A (`chips/<chip>/controls.toml`) and to C (the guest-state work of category
//! C, listed in the plan); `MODEL` and `MIRROR` rows without a model stay `unanswered`. The
//! display rows are answered by the display's board table (display/mod.rs), which asks
//! [`answer`] for its fallback; this hook in `Dispatcher::control` answers them only when
//! the display is switched off. Nothing here reaches the host (the ZBC setters with real
//! compression excepted, zbc.rs).
//!
//! The profiler classes (6.16) are refused at allocation: [`alloc`].

use std::collections::BTreeMap;

use crate::ctrl::Answer;
use crate::ver::{Abi, DAnswer, DRule};

/// D9 label of a `REFUSE` row (d-device-model.md §2).
pub const REFUSED: &str = "refused (feature absent on this board)";
/// D9 label of a `DENY` row.
pub const DENIED: &str = "refused (isolation)";
/// D9 label of an `ACK` row.
pub const ACKNOWLEDGED: &str = "synthesized (acknowledged, no effect)";
/// D9 label of the profiler class refusal.
pub const PROFILING_DENIED: &str = "refused (isolation: profiling is admin-only on the host)";

/// The controls with a hand-written model (roadmap R1, display/mod.rs), answered there.
pub const MODELLED: &[&str] = &[
    "NV0073_CTRL_CMD_SPECIFIC_HDCP_CTRL",
    "NV0073_CTRL_CMD_DP_CONFIGURE_FEC",
    "NV5070_CTRL_CMD_GET_RG_STATUS",
];

/// The controls the models of round 2 answer (d-device-model.md R2, the open MODEL rows
/// outside the display, the ZBC table): [`DState::control`], rc.rs, zbc.rs. The same list as
/// `MODELLED_HERE` of caraxes/tools/gsp-dtable.py, which lays out their parameter structs.
pub const MODELLED_HERE: &[&str] = &[
    "NV2080_CTRL_CMD_FIFO_DISABLE_CHANNELS",
    "NV2080_CTRL_CMD_GPU_REPORT_NON_REPLAYABLE_FAULT",
    "NV2080_CTRL_CMD_INTERNAL_RC_WATCHDOG_TIMEOUT",
    "NV2080_CTRL_CMD_INTERNAL_LOG_OOB_XID",
    "NV2080_CTRL_CMD_RC_SET_CLEAN_ERROR_HISTORY",
    "NV2080_CTRL_CMD_GPU_SET_COMPUTE_MODE_RULES",
    "NV0000_CTRL_CMD_GPUACCT_SET_ACCOUNTING_STATE",
    "NV2080_CTRL_CMD_GPU_VALIDATE_MEM_MAP_REQUEST",
    "NV9096_CTRL_CMD_SET_ZBC_COLOR_CLEAR",
    "NV9096_CTRL_CMD_SET_ZBC_DEPTH_CLEAR",
    "NV9096_CTRL_CMD_SET_ZBC_CLEAR_TABLE",
    "NV9096_CTRL_CMD_SET_ZBC_STENCIL_CLEAR",
    "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_HW_ENABLE",
    "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_RD_OFFSET",
    "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_WR_OFFSET",
    "NV0080_CTRL_CMD_DMA_FLUSH",
    "NV2080_CTRL_CMD_INTERNAL_MEMSYS_FLUSH_L2_ALL_RAMS_AND_CACHES",
    "NV2080_CTRL_CMD_INTERNAL_FBSR_INIT",
    "NV2080_CTRL_CMD_PERF_RATED_TDP_SET_CONTROL",
    "NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG",
];

/// Getters outside category D that answer from a model's state: the ZBC table entry
/// (category B) and the deprecated combined ZBC getter (A), the MMU debug mode of a
/// debugger session (B). `GET_ZBC_CLEAR_TABLE_SIZE` stays the chip-data row of chipctl.rs.
pub const MODEL_GETTERS: &[&str] = &[
    "NV9096_CTRL_CMD_GET_ZBC_CLEAR_TABLE_ENTRY",
    "NV9096_CTRL_CMD_GET_ZBC_CLEAR_TABLE",
    "NV83DE_CTRL_CMD_DEBUG_GET_MODE_MMU_DEBUG",
];

/// D9 labels of the small models.
pub const COMPUTE_MODE: &str = "guest (compute mode of this VM; never the host's)";
pub const GPUACCT: &str =
    "guest (accounting state of this VM recorded; no samples; never the host's)";
pub const BAR0_POLICY: &str = "guest (BAR0 map policy: deny by default)";
pub const FECS: &str = "synthesized (FECS trace setters recorded; FECS tracing is off, kgr.rs)";
pub const FLUSH: &str = "host (L2 flush on the device's own subdevice)";
pub const SUSPEND: &str =
    "guest (suspend recorded; the device's GSP state lives in the device process)";
pub const RATED_TDP: &str = "guest (RATED_TDP request recorded; never applied to the host)";
pub const DEBUGGER: &str =
    "guest (debugger session: MMU debug mode recorded; a fault is RC'd as without)";

/// What a D model may reach from the dispatcher for one control.
pub struct DCtx<'a> {
    /// The guest's channels, TSGs and VA spaces.
    pub reg: &'a crate::channel::Registry,
    /// The host mirrors of the guest's own channels and TSGs.
    pub mirror: Option<&'a mut dyn crate::rc::MirrorOps>,
    /// The device's host RM client (the L2 flush; with real compression the ZBC table,
    /// zbc.rs).
    pub host: Option<&'a mut (dyn crate::ctrl::HostRm + 'static)>,
    /// The guest BAR0 (bus address as the guest reported it, size).
    pub bar0: (u64, u64),
    /// The object the control names (hClient, hObject).
    pub object: (u32, u32),
}

/// The state of the D models of one VM (roadmap R2 and the open MODEL rows). Lives in the
/// dispatcher; nothing of it is the host's, and nothing of it reaches the host but the L2
/// flush, the per-channel controls on the guest's own mirrors (rc.rs) and, with real
/// compression, the ZBC setters (zbc.rs `SliceZbc`).
pub struct DState {
    chip: &'static crate::chip::ChipData,
    pub rc: crate::rc::RcState,
    /// Created at the first ZBC control from the chip's defaults (zbc.rs).
    pub zbc: Option<crate::zbc::ZbcTable>,
    /// With real compression (`CARAXES_COMPRESSION=slice`): the VM's share of the host's ZBC
    /// table, which answers the ZBC controls instead of `zbc` (zbc.rs `SliceZbc`).
    pub zbc_slice: Option<crate::zbc::SliceZbc>,
    pub compute_mode: u32,
    /// Accounting state by gpuId (`NV0000_CTRL_GPU_ACCOUNTING_STATE_*`).
    pub gpuacct: BTreeMap<u32, u32>,
    /// FECS trace: enable, read and write offset, as the guest kernel set them.
    pub fecs: (bool, u32, u32),
    /// The last FBSR_INIT: hClient, hSysMem, bEnteringGcoffState, suspend data address.
    pub fbsr: Option<(u32, u32, bool, u64)>,
    /// RATED_TDP client slots: client -> (action, vPstateType).
    pub rated_tdp: BTreeMap<u32, (u32, u32)>,
    /// MMU debug mode by debugger object (hClient, hObject).
    pub mmu_debug: BTreeMap<(u32, u32), u32>,
    /// BAR0 windows a non-root guest process may map ([offset, offset + size)): empty.
    pub bar0_allow: Vec<(u64, u64)>,
}

fn rd32(b: &[u8], o: usize) -> u32 {
    b.get(o..o + 4)
        .map_or(0, |s| u32::from_le_bytes(s.try_into().unwrap()))
}

fn rd64(b: &[u8], o: usize) -> u64 {
    b.get(o..o + 8)
        .map_or(0, |s| u64::from_le_bytes(s.try_into().unwrap()))
}

fn wr32(b: &mut [u8], o: usize, v: u32) {
    if let Some(s) = b.get_mut(o..o + 4) {
        s.copy_from_slice(&v.to_le_bytes());
    }
}

/// Offset of `path` in the version's generated layout of `st`.
fn off(st: &str, path: &str) -> usize {
    Abi::active()
        .layout(st)
        .unwrap_or_else(|| panic!("{st}: no generated layout"))
        .resolve(path)
        .unwrap_or_else(|e| panic!("{e}"))
        .0
}

fn enum_(name: &str) -> u32 {
    Abi::active()
        .d_enum(name)
        .unwrap_or_else(|| panic!("{name} is no enum of the generated D table"))
}

fn model(status: u32, params: &[u8], label: &'static str, note: String) -> Answer {
    Answer {
        status,
        params: params.to_vec(),
        label,
        note,
    }
}

/// The name of `cmd` if a model of this module answers it.
fn modelled_name(cmd: u32) -> Option<&'static str> {
    if let Some(r) = rule(cmd) {
        return MODELLED_HERE.contains(&r.name).then_some(r.name);
    }
    Abi::active()
        .routed
        .iter()
        .find(|r| r.id == cmd && MODEL_GETTERS.contains(&r.name))
        .map(|r| r.name)
}

impl DState {
    pub fn new(chip: &'static crate::chip::ChipData) -> Self {
        DState {
            chip,
            rc: crate::rc::RcState {
                selftest: crate::rc::SelfTest::from_env(),
                ..Default::default()
            },
            zbc: None,
            zbc_slice: crate::zbc::slice_from_env()
                .then(|| crate::zbc::SliceZbc::new(&chip.name, crate::zbc::max_from_env())),
            compute_mode: 0,
            gpuacct: BTreeMap::new(),
            fecs: (false, 0, 0),
            fbsr: None,
            rated_tdp: BTreeMap::new(),
            mmu_debug: BTreeMap::new(),
            bar0_allow: Vec::new(),
        }
    }

    /// `GSP_RM_ALLOC`: the profiler classes are refused ([`alloc`]); a handle allocated
    /// again drops what the models kept for its previous object; a channel's instance block
    /// is recorded for the fault path (rc.rs).
    pub fn alloc(
        &mut self,
        h_client: u32,
        h_object: u32,
        h_class: u32,
        params: &[u8],
    ) -> Option<Answer> {
        if let Some(a) = alloc(h_class) {
            return Some(a);
        }
        self.rc.forget(h_client, h_object);
        self.mmu_debug.remove(&(h_client, h_object));
        if h_class == self.chip.channel.gpfifo {
            self.rc.record_channel(h_client, h_object, params);
        }
        None
    }

    /// The models' answer to `cmd`, or `None` (not modelled here).
    pub fn control(&mut self, cx: &mut DCtx, cmd: u32, params: &[u8]) -> Option<Answer> {
        let name = modelled_name(cmd)?;
        let bad = status("NV_ERR_INVALID_ARGUMENT");
        let a = match name {
            "NV2080_CTRL_CMD_FIFO_DISABLE_CHANNELS" => {
                self.rc
                    .disable_channels(cx.reg, cx.mirror.as_deref_mut(), params)
            }
            "NV2080_CTRL_CMD_GPU_REPORT_NON_REPLAYABLE_FAULT" => {
                self.rc
                    .report_nr_fault(cx.reg, cx.mirror.as_deref_mut(), params)
            }
            "NV2080_CTRL_CMD_INTERNAL_RC_WATCHDOG_TIMEOUT" => self.rc.watchdog_timeout(params),
            "NV2080_CTRL_CMD_INTERNAL_LOG_OOB_XID" => self.rc.log_oob_xid(params),
            "NV2080_CTRL_CMD_RC_SET_CLEAN_ERROR_HISTORY" => self.rc.clean_history(params),
            n if n.starts_with("NV9096_") => {
                if let Some(s) = self.zbc_slice.as_mut() {
                    let host = cx
                        .host
                        .as_deref_mut()
                        .map(|h| h as &mut dyn crate::ctrl::HostRm);
                    return crate::zbc::slice_control(s, host, n, params);
                }
                let chip = &self.chip.name;
                let t = self
                    .zbc
                    .get_or_insert_with(|| crate::zbc::ZbcTable::for_chip(chip));
                return crate::zbc::control(t, n, params);
            }
            // ctrl2080gpu.h:1217-1290: the four rules; the kernel stores and enforces the
            // rule itself after the answer (subdevice_ctrl_gpu_kernel.c:2097-2121).
            "NV2080_CTRL_CMD_GPU_SET_COMPUTE_MODE_RULES" => {
                const P: &str = "NV2080_CTRL_GPU_SET_COMPUTE_MODE_RULES_PARAMS";
                let rules = rd32(params, off(P, "rules"));
                let legal = [
                    "NV2080_CTRL_GPU_COMPUTE_MODE_RULES_NONE",
                    "NV2080_CTRL_GPU_COMPUTE_MODE_RULES_EXCLUSIVE_COMPUTE",
                    "NV2080_CTRL_GPU_COMPUTE_MODE_RULES_COMPUTE_PROHIBITED",
                    "NV2080_CTRL_GPU_COMPUTE_MODE_RULES_EXCLUSIVE_COMPUTE_PROCESS",
                ];
                if legal.iter().any(|n| enum_(n) == rules) {
                    let was = std::mem::replace(&mut self.compute_mode, rules);
                    model(
                        0,
                        params,
                        COMPUTE_MODE,
                        format!("compute mode rules {was} -> {rules}"),
                    )
                } else {
                    model(
                        bad,
                        params,
                        COMPUTE_MODE,
                        format!("compute mode rules {rules}: no such rule"),
                    )
                }
            }
            // ctrl0000gpuacct.h:40-77; the kernel keeps its own accounting tables and turns
            // them on after NV_OK (client_resource.c:2061-2073).
            "NV0000_CTRL_CMD_GPUACCT_SET_ACCOUNTING_STATE" => {
                const P: &str = "NV0000_CTRL_GPUACCT_SET_ACCOUNTING_STATE_PARAMS";
                let gpu = rd32(params, off(P, "gpuId"));
                let state = rd32(params, off(P, "newState"));
                let on = enum_("NV0000_CTRL_GPU_ACCOUNTING_STATE_ENABLED");
                let disabled = enum_("NV0000_CTRL_GPU_ACCOUNTING_STATE_DISABLED");
                if state != on && state != disabled {
                    model(
                        bad,
                        params,
                        GPUACCT,
                        format!("accounting state {state} of gpu {gpu:#x}: no such state"),
                    )
                } else {
                    self.gpuacct.insert(gpu, state);
                    let what = if state == on { "enabled" } else { "disabled" };
                    model(
                        0,
                        params,
                        GPUACCT,
                        format!("accounting of gpu {gpu:#x} {what}"),
                    )
                }
            }
            "NV2080_CTRL_CMD_GPU_VALIDATE_MEM_MAP_REQUEST" => self.bar0_policy(cx.bar0, params),
            "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_HW_ENABLE" => {
                let o = off(
                    "NV2080_CTRL_INTERNAL_GR_FECS_TRACE_HW_ENABLE_PARAMS",
                    "bEnable",
                );
                let en = params.get(o).copied().unwrap_or(0) != 0;
                self.fecs.0 = en;
                model(
                    0,
                    params,
                    FECS,
                    format!("FECS trace hardware enable {}", en as u8),
                )
            }
            "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_RD_OFFSET"
            | "NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_WR_OFFSET" => {
                let o = rd32(
                    params,
                    off("NV2080_CTRL_INTERNAL_GR_FECS_TRACE_OFFSET_PARAMS", "offset"),
                );
                let read = name.ends_with("RD_OFFSET");
                if read {
                    self.fecs.1 = o;
                } else {
                    self.fecs.2 = o;
                }
                let which = if read { "read" } else { "write" };
                model(0, params, FECS, format!("FECS trace {which} offset {o:#x}"))
            }
            // ctrl0080dma.h:248-291: L2 is written back; COMPTAG has nothing to clean (no
            // compression, D16); FB has nothing the device holds back.
            "NV0080_CTRL_CMD_DMA_FLUSH" => {
                let unit = rd32(params, off("NV0080_CTRL_DMA_FLUSH_PARAMS", "targetUnit"));
                let l2 = (unit >> enum_("NV0080_CTRL_DMA_FLUSH_TARGET_UNIT_L2")) & 1 != 0;
                let ops: &[crate::hostabi::L2Flush] = if l2 {
                    &[crate::hostabi::L2Flush::WriteBack]
                } else {
                    &[]
                };
                let note = format!(
                    "DMA flush targetUnit {unit:#x}: L2 {}, COMPTAG ignored (no compression, D16), FB nothing to flush",
                    if l2 { "written back" } else { "not asked" }
                );
                self.flush(cx, ops, params, note)
            }
            "NV2080_CTRL_CMD_INTERNAL_MEMSYS_FLUSH_L2_ALL_RAMS_AND_CACHES" => {
                let ops = [
                    crate::hostabi::L2Flush::WriteBack,
                    crate::hostabi::L2Flush::Invalidate,
                ];
                self.flush(
                    cx,
                    &ops,
                    params,
                    "flush L2 all RAMs and caches: write back and evict".into(),
                )
            }
            "NV2080_CTRL_CMD_INTERNAL_FBSR_INIT" => {
                const P: &str = "NV2080_CTRL_INTERNAL_FBSR_INIT_PARAMS";
                let r = (
                    rd32(params, off(P, "hClient")),
                    rd32(params, off(P, "hSysMem")),
                    params
                        .get(off(P, "bEnteringGcoffState"))
                        .copied()
                        .unwrap_or(0)
                        != 0,
                    rd64(params, off(P, "sysmemAddrOfSuspendResumeData")),
                );
                self.fbsr = Some(r);
                model(
                    0,
                    params,
                    SUSPEND,
                    format!(
                        "FBSR init: sysmem {:#x}/{:#x}, GCOFF {}, suspend data {:#x}",
                        r.0, r.1, r.2 as u8, r.3
                    ),
                )
            }
            // ctrl2080perf.h:212-255, :409-424: one slot per arbitration client.
            "NV2080_CTRL_CMD_PERF_RATED_TDP_SET_CONTROL" => {
                const P: &str = "NV2080_CTRL_PERF_RATED_TDP_CONTROL_PARAMS";
                let client = rd32(params, off(P, "client"));
                let input = rd32(params, off(P, "input"));
                let vp = rd32(params, off(P, "vPstateType"));
                self.rated_tdp.insert(client, (input, vp));
                model(
                    0,
                    params,
                    RATED_TDP,
                    format!("RATED_TDP client {client}: action {input}, vPstate type {vp}"),
                )
            }
            // ctrl83dedebug.h:96-153: per debugger session, SET ENABLE 1 / DISABLE 2, GET
            // ENABLED 1 / DISABLED 2.
            "NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG" => {
                let action = rd32(
                    params,
                    off("NV83DE_CTRL_DEBUG_SET_MODE_MMU_DEBUG_PARAMS", "action"),
                );
                let en = enum_("NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG_ENABLE");
                let dis = enum_("NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG_DISABLE");
                if action != en && action != dis {
                    model(
                        bad,
                        params,
                        DEBUGGER,
                        format!("MMU debug action {action}: no such action"),
                    )
                } else {
                    self.mmu_debug.insert(cx.object, action);
                    let what = if action == en { "enabled" } else { "disabled" };
                    model(
                        0,
                        params,
                        DEBUGGER,
                        format!("MMU debug {what} on {:#x}/{:#x}", cx.object.0, cx.object.1),
                    )
                }
            }
            "NV83DE_CTRL_CMD_DEBUG_GET_MODE_MMU_DEBUG" => {
                let en = self.mmu_debug.get(&cx.object)
                    == Some(&enum_("NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG_ENABLE"));
                let v = enum_(if en {
                    "NV83DE_CTRL_CMD_DEBUG_GET_MODE_MMU_DEBUG_ENABLED"
                } else {
                    "NV83DE_CTRL_CMD_DEBUG_GET_MODE_MMU_DEBUG_DISABLED"
                });
                let mut b = params.to_vec();
                wr32(
                    &mut b,
                    off("NV83DE_CTRL_DEBUG_GET_MODE_MMU_DEBUG_PARAMS", "value"),
                    v,
                );
                Answer {
                    status: 0,
                    params: b,
                    label: DEBUGGER,
                    note: format!("MMU debug mode {v}"),
                }
            }
            _ => return None,
        };
        Some(a)
    }

    /// With real compression, the guest kernel's `INTERNAL_MEMSYS_SET_ZBC_REFERENCED`
    /// (zbc.rs `referenced`); `None` otherwise, and chipctl.rs acknowledges it as before.
    pub fn zbc_referenced(&mut self, cmd: u32, params: &[u8]) -> Option<Answer> {
        let s = self.zbc_slice.as_mut()?;
        let id = Abi::active()
            .routed("NV0080_CTRL_CMD_INTERNAL_MEMSYS_SET_ZBC_REFERENCED")?
            .id;
        (cmd == id).then(|| crate::zbc::referenced(s, params))
    }

    /// VM exit: what the VM leaves in the host's ZBC table (real compression only).
    pub fn release_zbc(&mut self) -> Vec<String> {
        self.zbc_slice
            .as_mut()
            .map(|s| s.release())
            .unwrap_or_default()
    }

    /// The BAR0 map policy (6.4 rule 3): the kernel answers PTIMER, the usermode page and
    /// PMC itself and sends only the other BAR0 ranges, with the absolute bus address
    /// (subdevice_ctrl_gpu_kernel.c:2918-2995). A range outside BAR0, empty or wrapping is a
    /// protection fault; inside, only an allow-list window is mapped, and the list is empty:
    /// a non-root guest process never maps the registers the guest kernel owns.
    fn bar0_policy(&self, bar0: (u64, u64), params: &[u8]) -> Answer {
        const P: &str = "NV2080_CTRL_GPU_VALIDATE_MEM_MAP_REQUEST_PARAMS";
        let fault = status("NV_ERR_PROTECTION_FAULT");
        let start = rd64(params, off(P, "addressStart"));
        let len = rd64(params, off(P, "addressLength"));
        let (base, size) = bar0;
        let range = start
            .checked_sub(base)
            .filter(|_| base != 0 && len != 0)
            .and_then(|o| o.checked_add(len).filter(|&e| e <= size).map(|e| (o, e)));
        let Some((o, e)) = range else {
            return model(
                fault,
                params,
                BAR0_POLICY,
                format!("map {start:#x}+{len:#x}: outside the guest BAR0 {base:#x}+{size:#x}"),
            );
        };
        if self.bar0_allow.iter().any(|&(a, n)| o >= a && e <= a + n) {
            return model(
                0,
                params,
                BAR0_POLICY,
                format!("map BAR0 [{o:#x}, {e:#x}): in the allow-list"),
            );
        }
        model(
            fault,
            params,
            BAR0_POLICY,
            format!("map BAR0 [{o:#x}, {e:#x}): not in the allow-list (empty)"),
        )
    }

    /// The guest's cache operation as `FB_FLUSH_GPU_CACHE` on the device's own subdevice
    /// (the flag bits of the host driver, as ctrl.rs `host_flush_gpu_cache`); NV_OK without
    /// a host: then there is no physical L2 behind the device.
    fn flush(
        &mut self,
        cx: &mut DCtx,
        ops: &[crate::hostabi::L2Flush],
        params: &[u8],
        mut note: String,
    ) -> Answer {
        let Some(host) = cx.host.as_deref_mut() else {
            note.push_str("; no host RM: nothing to flush");
            return model(0, params, FLUSH, note);
        };
        let l = crate::hostabi::current();
        for &op in ops {
            let mut p = l.flush_gpu_cache(op);
            let st = host.control(
                crate::ver::common::NV20_SUBDEVICE_0,
                crate::hostabi::CMD_FB_FLUSH_GPU_CACHE,
                &mut p,
            );
            note.push_str(&format!(
                "; host FB_FLUSH_GPU_CACHE flags {:#x}: status {st:#x}",
                l.flush_gpu_cache_flags(op)
            ));
        }
        model(0, params, FLUSH, note)
    }
}

/// An NV status by name, from the version's nvstatuscodes.h (generated `D_ENUMS`).
pub fn status(name: &str) -> u32 {
    Abi::active()
        .d_enum(name)
        .unwrap_or_else(|| panic!("{name} is no status of the generated D table"))
}

/// The rule of `cmd` in the guest ABI in force.
pub fn rule(cmd: u32) -> Option<&'static DRule> {
    Abi::active().d_rule(cmd)
}

/// A D control the plan moves to category A: answered by the chip-data table of chipctl.rs
/// (the display's fallback leaves it to that table).
pub fn moved_to_a(cmd: u32) -> bool {
    rule(cmd).is_some_and(|r| r.reclass == 'A')
}

/// The generic answer of the rule table to `cmd`, or `None` (no D control, or a row this
/// table does not answer: moved to A, C or E, or a MODEL or MIRROR row).
pub fn answer(cmd: u32, params: &[u8]) -> Option<Answer> {
    let r = rule(cmd)?;
    if r.reclass != '-' {
        return None;
    }
    let (label, kind) = match r.answer {
        DAnswer::Refuse => (REFUSED, "REFUSE"),
        DAnswer::Deny => (DENIED, "DENY"),
        DAnswer::Ack => (ACKNOWLEDGED, "ACK"),
        DAnswer::Table | DAnswer::Model | DAnswer::Mirror => return None,
    };
    Some(Answer {
        status: r.status,
        params: params.to_vec(),
        label,
        note: format!(
            "{} ({cmd:#x}, {} bytes): D rule {kind}{}, group {} rank {} (d-controls.tsv)",
            r.name,
            params.len(),
            if r.why.is_empty() {
                String::new()
            } else {
                format!(" ({})", r.why)
            },
            r.group,
            r.rank
        ),
    })
}

/// `GSP_RM_ALLOC` of a profiler class: NV_ERR_INSUFFICIENT_PERMISSIONS, the answer a stock
/// system gives a user under RmProfilingAdminOnly=1 (6.16): HWPM, PMA and SMPC are
/// chip-wide, and a reservation would stream the host desktop's counters into the guest.
pub fn alloc(class: u32) -> Option<Answer> {
    let &(_, name) = Abi::active()
        .profiler_classes
        .iter()
        .find(|c| c.0 == class)?;
    Some(Answer {
        status: status("NV_ERR_INSUFFICIENT_PERMISSIONS"),
        params: Vec::new(),
        label: PROFILING_DENIED,
        note: format!(
            "alloc {name} {class:#x}: profiler classes are refused (d-device-model.md 6.16)"
        ),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ctrl::{Dispatcher, HostRm, INTERNAL_CLIENT, INTERNAL_SUBDEVICE};
    use crate::ver::{common as v, ABIS};
    use std::collections::BTreeSet;
    use std::sync::{Arc, Mutex};

    /// Records every control that reaches the host.
    struct Rec(Arc<Mutex<Vec<u32>>>);
    impl HostRm for Rec {
        fn control(&mut self, _: u32, cmd: u32, _: &mut [u8]) -> u32 {
            self.0.lock().unwrap().push(cmd);
            v::NV_OK
        }
    }

    fn tu106() -> &'static crate::chip::ChipData {
        crate::chip::by_name("tu106").unwrap().data()
    }

    fn dispatcher(host: Option<Box<dyn HostRm>>) -> Dispatcher {
        let f = crate::fixture::rtx2070();
        Dispatcher::new(tu106(), &f.identity(4 << 30), host)
    }

    fn counts(abi: &Abi) -> [usize; 6] {
        let mut c = [0usize; 6];
        for r in abi.d_rules {
            c[r.answer as usize] += 1;
        }
        c
    }

    /// The table covers every category D control of the inventory no other handler
    /// answers, once, with the plan's counts (d-device-model.md §5: 200 REFUSE, 37 DENY,
    /// 21 ACK, 42 MODEL, 3 MIRROR, 5 TABLE in 615; 610 lacks the three 615-only controls).
    #[test]
    fn every_d_control_has_exactly_one_rule() {
        for abi in ABIS {
            let ids: Vec<u32> = abi.d_rules.iter().map(|r| r.id).collect();
            let set: BTreeSet<u32> = ids.iter().copied().collect();
            assert_eq!(set.len(), ids.len(), "{}: a control twice", abi.name);
            assert_eq!(ids.len(), abi.d_inventory, "{}", abi.name);
            let inv: BTreeSet<u32> = abi
                .routed
                .iter()
                .filter(|r| r.category == 'D' && !r.other)
                .map(|r| r.id)
                .collect();
            assert_eq!(
                set, inv,
                "{}: the rule table and the inventory's D",
                abi.name
            );
            for r in abi.d_rules {
                assert_eq!(abi.routed(r.name).map(|x| x.id), Some(r.id), "{}", r.name);
                assert!("-ACE".contains(r.reclass), "{}", r.name);
                assert!((1..=5).contains(&r.rank), "{}", r.name);
                if r.answer == DAnswer::Model {
                    assert!(!r.model.is_empty(), "{}: MODEL without a model", r.name);
                }
            }
        }
        // Refuse, Deny, Ack, Table, Model, Mirror. Round 2 (d-device-model.md §10): the two
        // timed-semaphore rows REFUSE until Q4 shows the class, GPU accounting a model. The
        // reconciliation of 2026-09-25: of the 17 rows moved to C, the twelve the C table
        // answers (public.rs) have left this table (3 REFUSE, 7 MODEL, 2 MIRROR); the five
        // the D models answer stay, with reclass C.
        let by_name = |n: &str| ABIS.iter().find(|a| a.name == n).unwrap();
        assert_eq!(counts(by_name("615")), [199, 37, 20, 5, 34, 1]);
        assert_eq!(counts(by_name("610")), [197, 37, 19, 5, 34, 1]);
        for abi in ABIS {
            let re = |c: char| abi.d_rules.iter().filter(|r| r.reclass == c).count();
            assert_eq!((re('A'), re('C'), re('E')), (7, 5, 102), "{}", abi.name);
        }
    }

    /// The statuses the plan names: INVALID_ARGUMENT for the three header-named refusals,
    /// INSUFFICIENT_PERMISSIONS for the host-global scheduler knobs, the DRAM setters and
    /// the profiler permission controls, NOT_SUPPORTED for every other refusal and denial.
    #[test]
    fn statuses_are_the_plans() {
        let abi = Abi::active();
        let invalid_argument = status("NV_ERR_INVALID_ARGUMENT");
        let insufficient = status("NV_ERR_INSUFFICIENT_PERMISSIONS");
        let with = |st: u32| -> BTreeSet<&str> {
            abi.d_rules
                .iter()
                .filter(|r| matches!(r.answer, DAnswer::Refuse | DAnswer::Deny) && r.status == st)
                .map(|r| r.name)
                .collect()
        };
        assert_eq!(
            with(invalid_argument),
            BTreeSet::from([
                "NV0073_CTRL_CMD_DP_GET_EDP_DATA",
                "NV5070_CTRL_CMD_GET_PINSET_PEER",
                "NV5070_CTRL_CMD_GET_PINSET_LOCKPINS",
            ])
        );
        assert_eq!(
            with(insufficient),
            BTreeSet::from([
                "NV0080_CTRL_CMD_FIFO_STOP_RUNLIST",
                "NV0080_CTRL_CMD_FIFO_START_RUNLIST",
                "NV2080_CTRL_CMD_FIFO_CONFIG_CTXSW_TIMEOUT",
                "NV2080_CTRL_CMD_FIFO_RUNLIST_SET_SCHED_POLICY",
                "NV2080_CTRL_CMD_FB_SET_RRD",
                "NV2080_CTRL_CMD_FB_SET_READ_LIMIT",
                "NV2080_CTRL_CMD_FB_SET_WRITE_LIMIT",
                "NV2080_CTRL_CMD_PERF_RESERVE_PERFMON_HW",
                "NVB0CC_CTRL_CMD_INTERNAL_PERMISSIONS_INIT",
            ])
        );
        for r in abi.d_rules {
            match r.answer {
                DAnswer::Refuse | DAnswer::Deny => assert!(
                    [v::NV_ERR_NOT_SUPPORTED, invalid_argument, insufficient].contains(&r.status),
                    "{}",
                    r.name
                ),
                DAnswer::Ack => assert_eq!(r.status, v::NV_OK, "{}", r.name),
                _ => {}
            }
        }
    }

    /// Through the dispatcher, every row that stays in D gets its label (REFUSE, DENY and
    /// ACK answered here or by the display's board table, the modelled rows by their model,
    /// the other MODEL and MIRROR rows unanswered), the moved rows are someone else's (E
    /// refused by the family rule, A by the chip table or unanswered while open, C
    /// unanswered unless modelled), and no D control reaches the host but the L2 flush of
    /// the two flush rows.
    #[test]
    fn the_dispatcher_answers_every_d_control_by_its_rule() {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut d = dispatcher(Some(Box::new(Rec(seen.clone()))));
        let chip = tu106();
        for r in Abi::active().d_rules {
            let req = vec![0xA5u8; r.size.max(4)];
            let a = d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, r.id, &req);
            // SET_DEFAULT_VASPACE is now a stateful device control. This inventory sweep
            // deliberately sends every command to the internal subdevice, so validation
            // rejects this row before the chip feature fallback.
            if r.id == 0x0080_1812 {
                assert_eq!(
                    (a.status, a.label),
                    (0x33, "guest (validated default VAS association)"),
                    "{}",
                    r.name
                );
                continue;
            }
            // The Windows KMD's GfxP pool (recorded.rs) is answered before this table.
            if crate::recorded::OVERRIDES.contains(&r.id) {
                assert_eq!(a.label, crate::recorded::LABEL_CHIP, "{}", r.name);
                continue;
            }
            if MODELLED_HERE.contains(&r.name) {
                assert!(
                    !["unanswered", REFUSED, DENIED].contains(&a.label),
                    "{}: {}",
                    r.name,
                    a.label
                );
                continue;
            }
            match (r.reclass, r.answer) {
                ('-', DAnswer::Refuse) => {
                    assert_eq!((a.status, a.label), (r.status, REFUSED), "{}", r.name);
                    assert_eq!(a.params, req, "{}: a refusal echoes the request", r.name);
                }
                ('-', DAnswer::Deny) => {
                    assert_eq!((a.status, a.label), (r.status, DENIED), "{}", r.name)
                }
                ('-', DAnswer::Ack) => {
                    assert_eq!((a.status, a.label), (v::NV_OK, ACKNOWLEDGED), "{}", r.name);
                    assert_eq!(a.params, req, "{}", r.name);
                }
                // The display models (MODELLED) need the display, which this dispatcher
                // has switched off: unanswered here, answered in the next test.
                ('-', _) => assert_eq!(a.label, "unanswered", "{}", r.name),
                // A C row left in this table is a D model's (above); the C table's rows
                // (public.rs) are no D rules any more (the reconciliation of 2026-09-25).
                ('C', _) => panic!("{}: a C row no D model answers", r.name),
                ('E', _) => {
                    let acked = chip.features().acked.contains_key(&r.id);
                    assert_eq!(
                        a.label,
                        if acked {
                            crate::chipctl::ACKED
                        } else {
                            crate::chipctl::REFUSED
                        },
                        "{}",
                        r.name
                    );
                }
                ('A', _) => {
                    if chip.controls().entries.contains_key(&r.id) {
                        assert_ne!(a.label, "unanswered", "{}", r.name);
                    } else {
                        assert!(
                            chip.controls().open.iter().any(|o| o.0 == r.id),
                            "{}: an A row is a controls.toml row or an open one",
                            r.name
                        );
                    }
                }
                _ => unreachable!(),
            }
        }
        let flush = crate::hostabi::CMD_FB_FLUSH_GPU_CACHE;
        assert!(
            seen.lock().unwrap().iter().all(|&c| c == flush),
            "{:x?}",
            seen.lock().unwrap()
        );
        // DMA_FLUSH with 0xA5 has the L2 bit: one write-back; FLUSH_L2_ALL_RAMS: two.
        assert_eq!(seen.lock().unwrap().len(), 3);
    }

    /// The display's board table gives the display rows the same answer as the hook: with
    /// the display switched on, the fallback asks the rule table.
    #[test]
    fn the_display_board_table_answers_the_display_rows() {
        let board = crate::board::Board::load("rtx2070").unwrap();
        let mut disp = crate::display::Display::from_setup(&crate::display::Setup {
            enabled: true,
            chip: "tu106".into(),
            board: board.display,
        })
        .unwrap();
        for r in Abi::active().d_rules.iter().filter(|r| r.group == "disp") {
            let req = vec![0u8; r.size.max(8)];
            let a = disp.control(r.id, &req);
            match (r.reclass, r.answer) {
                ('-', DAnswer::Refuse | DAnswer::Deny | DAnswer::Ack) => {
                    let want = answer(r.id, &req).unwrap();
                    let a = a.unwrap_or_else(|| panic!("{}", r.name));
                    assert_eq!((a.status, a.label), (want.status, want.label), "{}", r.name);
                }
                ('A' | 'E', _) => assert!(a.is_none(), "{}: left to the chip tables", r.name),
                ('-', _) if MODELLED.contains(&r.name) => {
                    let a = a.unwrap_or_else(|| panic!("{}", r.name));
                    assert_ne!(a.label, "unanswered", "{}", r.name);
                }
                _ => {}
            }
        }
    }

    /// The guard that keeps host-wide setters off the host (d-device-model.md R0): no D
    /// control is in FORWARD, the GSS legacy list, BINAPI or MIRROR_FORWARDED, in either
    /// ABI.
    #[test]
    fn no_d_control_is_forwarded() {
        // MIRROR_FORWARDED is private to ctrl.rs: read its entries from the source and
        // resolve the names this guard knows (a new entry fails here until it is added).
        let src = include_str!("ctrl.rs");
        let block = src
            .split("const MIRROR_FORWARDED: &[u32] = &[")
            .nth(1)
            .and_then(|s| s.split("];").next())
            .expect("MIRROR_FORWARDED in ctrl.rs");
        let known = [
            ("CMD_CHANNEL_STOP", v::CMD_CHANNEL_STOP),
            ("CMD_TSG_PREEMPT", v::CMD_TSG_PREEMPT),
            ("CMD_TSG_SET_TIMESLICE", v::CMD_TSG_SET_TIMESLICE),
            (
                "CMD_CHANNEL_GPFIFO_SCHEDULE",
                v::CMD_CHANNEL_GPFIFO_SCHEDULE,
            ),
            ("CMD_TSG_GPFIFO_SCHEDULE", v::CMD_TSG_GPFIFO_SCHEDULE),
        ];
        let mut mirror = Vec::new();
        for name in block
            .split(',')
            .map(|s| s.trim().trim_start_matches("v::"))
            .filter(|s| !s.is_empty() && !s.starts_with("//"))
        {
            let id = known
                .iter()
                .find(|k| k.0 == name)
                .unwrap_or_else(|| panic!("MIRROR_FORWARDED entry {name}: add it to this guard"))
                .1;
            mirror.push(id);
        }
        let mut forwarded: Vec<(u32, &str)> = Vec::new();
        forwarded.extend(v::FORWARD.iter().map(|&(id, n)| (id, n)));
        forwarded.extend(v::LEGACY.iter().map(|&(id, _, n)| (id, n)));
        forwarded.extend(v::BINAPI.iter().map(|&id| (id, "BINAPI")));
        forwarded.extend(mirror.iter().map(|&id| (id, "MIRROR_FORWARDED")));
        for abi in ABIS {
            for r in abi.d_rules {
                if let Some((_, list)) = forwarded.iter().find(|f| f.0 == r.id) {
                    panic!("{} ({:#x}) is D and in {list}", r.name, r.id);
                }
            }
        }
    }

    /// GSP_RM_ALLOC of the four profiler classes is refused with
    /// NV_ERR_INSUFFICIENT_PERMISSIONS and the object is not recorded; other classes are not.
    #[test]
    fn profiler_classes_are_refused() {
        let mut d = dispatcher(None);
        let classes: Vec<u32> = Abi::active().profiler_classes.iter().map(|c| c.0).collect();
        assert_eq!(classes, [0x90CC, 0xB0CC, 0xB1CC, 0xB2CC]);
        for (i, &c) in classes.iter().enumerate() {
            let h = 0x5000 + i as u32;
            let a = d.alloc(INTERNAL_CLIENT, h, INTERNAL_SUBDEVICE, c, &[0u8; 16]);
            assert_eq!(
                (a.status, a.label),
                (status("NV_ERR_INSUFFICIENT_PERMISSIONS"), PROFILING_DENIED),
                "{c:#x}"
            );
            // A control on the refused object is not answered as the profiler's object.
            let perm = Abi::active()
                .d_rules
                .iter()
                .find(|r| r.name == "NVB0CC_CTRL_CMD_INTERNAL_PERMISSIONS_INIT")
                .unwrap();
            let a = d.control(INTERNAL_CLIENT, h, perm.id, &vec![0u8; perm.size]);
            assert_eq!(a.status, status("NV_ERR_INSUFFICIENT_PERMISSIONS"));
        }
        let a = d.alloc(
            INTERNAL_CLIENT,
            0x6000,
            INTERNAL_SUBDEVICE,
            0x90E7,
            &[0u8; 8],
        );
        assert_eq!(a.status, v::NV_OK);
    }

    /// The two layout changes between 610 and 615 (d-device-model.md §4) come from the
    /// generated layout tables: PERMISSIONS_INIT loses bAdminProfilingPermitted (7 to 6
    /// bytes, every later flag one byte up), CONTROL_GSP_TRACE gains targetTask before
    /// `flag` (offset 24 to 26), and both rules carry the version's size.
    #[test]
    fn the_two_layout_changes_are_generated() {
        let by = |n: &str| ABIS.iter().find(|a| a.name == n).unwrap();
        let (a610, a615) = (by("610"), by("615"));
        let perm = "NVB0CC_CTRL_INTERNAL_PERMISSIONS_INIT_PARAMS";
        let (p610, p615) = (a610.layout(perm).unwrap(), a615.layout(perm).unwrap());
        assert_eq!((p610.size, p615.size), (7, 6));
        assert!(p610.resolve("bAdminProfilingPermitted").is_ok());
        assert!(p615.resolve("bAdminProfilingPermitted").is_err());
        assert_eq!(
            p610.resolve("bDevProfilingPermitted").unwrap().0,
            p615.resolve("bDevProfilingPermitted").unwrap().0 + 1
        );
        let trace = "NV2080_CTRL_CMD_INTERNAL_CONTROL_GSP_TRACE_PARAMS";
        let (t610, t615) = (a610.layout(trace).unwrap(), a615.layout(trace).unwrap());
        assert_eq!((t610.size, t615.size), (32, 32));
        assert_eq!(t610.resolve("flag").unwrap().0, 24);
        assert_eq!(t615.resolve("flag").unwrap().0, 26);
        assert!(t610.resolve("targetTask").is_err());
        assert_eq!(t615.resolve("targetTask").unwrap(), (24, 2));
        for (abi, want) in [(a610, (7, 32)), (a615, (6, 32))] {
            let size = |n: &str| abi.d_rules.iter().find(|r| r.name == n).unwrap().size;
            assert_eq!(
                (
                    size("NVB0CC_CTRL_CMD_INTERNAL_PERMISSIONS_INIT"),
                    size("NV2080_CTRL_CMD_INTERNAL_CONTROL_GSP_TRACE")
                ),
                want,
                "{}",
                abi.name
            );
        }
    }

    /// The 102 rows that move to E are feature families beside the E families, every id
    /// once, and TU106 names them all absent while GB206 has the Blackwell ones.
    #[test]
    fn the_e_rows_are_families() {
        for abi in ABIS {
            let ids: Vec<u32> = abi
                .d_families
                .iter()
                .flat_map(|f| f.controls.iter().map(|c| c.0))
                .collect();
            let set: BTreeSet<u32> = ids.iter().copied().collect();
            assert_eq!((set.len(), ids.len()), (102, 102), "{}", abi.name);
            let e: BTreeSet<u32> = abi
                .d_rules
                .iter()
                .filter(|r| r.reclass == 'E')
                .map(|r| r.id)
                .collect();
            assert_eq!(set, e, "{}", abi.name);
            for f in abi.d_families {
                assert!(!f.headers.is_empty(), "{}", f.name);
                assert!(!abi.families.iter().any(|g| g.name == f.name), "{}", f.name);
            }
            for id in abi.d_e_ack {
                assert!(set.contains(id));
            }
        }
        let gb = crate::chip::by_name("gb206").unwrap().data();
        let present: BTreeSet<&str> = Abi::active()
            .d_families
            .iter()
            .map(|f| f.name)
            .filter(|n| !gb.features().absent.contains(n))
            .collect();
        assert_eq!(
            present,
            BTreeSet::from([
                "frl",
                "dp2x",
                "display_later",
                "ampere_later",
                "row_remap",
                "blackwell"
            ])
        );
        let tu = &tu106().features();
        for f in Abi::active().d_families {
            assert!(tu.absent.contains(&f.name), "{}", f.name);
        }
    }

    /// The R1 setters without a model: PERF_NOTIFY_VIDEOEVENT (NVENC through Sunshine, 6.9)
    /// is acknowledged through the dispatcher, request echoed, never forwarded.
    #[test]
    fn notify_videoevent_is_acknowledged() {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut d = dispatcher(Some(Box::new(Rec(seen.clone()))));
        let r = Abi::active()
            .d_rules
            .iter()
            .find(|r| r.name == "NV2080_CTRL_CMD_PERF_NOTIFY_VIDEOEVENT")
            .unwrap();
        let req: Vec<u8> = (0..r.size as u8).collect();
        let a = d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, r.id, &req);
        assert_eq!(
            (a.status, a.label, &a.params),
            (v::NV_OK, ACKNOWLEDGED, &req)
        );
        assert!(seen.lock().unwrap().is_empty());
    }

    /// With every family present, the D rows that move to E fall through every other
    /// handler unanswered: the family rule takes nothing another handler answers.
    #[test]
    fn e_rows_have_no_other_handler() {
        for r in Abi::active().d_rules.iter().filter(|r| r.reclass == 'E') {
            assert!(answer(r.id, &[0u8; 8]).is_none(), "{}", r.name);
        }
    }

    /// The guard of the reconciliation (2026-09-25): no control id is answered by two of
    /// the three table-driven handlers, the GSP plan's table (public.rs: `PUBLIC` and
    /// `PUBLIC_C`), the chip-data and feature-family rules (chipctl.rs: controls.toml of
    /// every chip, the E families and the D rows moved to E) and the D models with the rule
    /// table (dmodel.rs, rc.rs, zbc.rs: the rows that stay in D or are C rows a model
    /// answers, and the model getters). Walked per ABI over the generated tables, then,
    /// for the ABI of this build, through the three handlers themselves (a handler that
    /// answers is one that returns `Some`).
    #[test]
    fn no_control_is_answered_by_two_tables() {
        use crate::ver::common::public as p;
        let public: BTreeSet<u32> = p::PUBLIC.iter().chain(p::PUBLIC_C).map(|c| c.id).collect();
        let chips: Vec<&'static crate::chip::ChipData> = crate::chip::CHIPS
            .iter()
            .map(|n| crate::chip::by_name(n).unwrap().data())
            .collect();
        for abi in ABIS {
            let mut chipctl: BTreeSet<u32> = abi
                .families
                .iter()
                .chain(abi.d_families)
                .flat_map(|f| f.controls.iter().map(|c| c.0))
                .collect();
            for chip in &chips {
                chipctl.extend(chip.controls().entries.keys());
            }
            let mut d: BTreeSet<u32> = abi
                .d_rules
                .iter()
                .filter(|r| "-C".contains(r.reclass))
                .map(|r| r.id)
                .collect();
            d.extend(
                MODELLED_HERE
                    .iter()
                    .chain(MODEL_GETTERS)
                    .filter_map(|n| abi.routed(n).map(|r| r.id)),
            );
            for (a, an, b, bn) in [
                (&public, "public.rs", &chipctl, "chipctl.rs"),
                (&public, "public.rs", &d, "dmodel.rs/rc.rs"),
                (&chipctl, "chipctl.rs", &d, "dmodel.rs/rc.rs"),
            ] {
                let both: Vec<String> = a.intersection(b).map(|id| format!("{id:#x}")).collect();
                assert!(both.is_empty(), "{}: answered by {an} and by {bn}: {both:?}", abi.name);
            }
        }
        // The handlers of this build.
        let reg = crate::channel::Registry::new(tu106().channel);
        let buf = vec![0u8; 1 << 16];
        let abi = Abi::active();
        let ids: BTreeSet<u32> = abi
            .routed
            .iter()
            .map(|r| r.id)
            .chain(public.iter().copied())
            .collect();
        for chip in &chips {
            for &id in &ids {
                let size = p::public_control(id).map_or(buf.len(), |c| if c.size == 0 { 16 } else { c.size });
                let mut attrs = crate::public::GuestAttrs::default();
                let mut rc = crate::rc::RcState::default();
                let mut ctx = crate::public::Ctx {
                    host: None,
                    reservation: None,
                    chip,
                    now_ns: 0,
                    object: (INTERNAL_CLIENT, INTERNAL_SUBDEVICE),
                    key: (INTERNAL_CLIENT, INTERNAL_SUBDEVICE),
                    mirror: None,
                    attrs: &mut attrs,
                    rc: &mut rc,
                    reg: Some(&reg),
                    link_control: 0,
                };
                let by_public = crate::public::answer(&mut ctx, id, &buf[..size]).is_some();
                let by_chipctl = crate::chipctl::answer(chip, id, &buf).is_some();
                let mut cx = DCtx {
                    reg: &reg,
                    mirror: None,
                    host: None,
                    bar0: (0xE000_0000, 16 << 20),
                    object: (INTERNAL_CLIENT, INTERNAL_SUBDEVICE),
                };
                let by_d = DState::new(chip).control(&mut cx, id, &buf).is_some()
                    || answer(id, &buf).is_some();
                assert!(
                    [by_public, by_chipctl, by_d].iter().filter(|&&x| x).count() <= 1,
                    "{} on {}: {id:#x} answered by public.rs {by_public}, chipctl.rs {by_chipctl}, dmodel.rs/rc.rs {by_d}",
                    abi.name,
                    chip.name
                );
            }
        }
    }

    fn id(name: &str) -> u32 {
        Abi::active()
            .d_rules
            .iter()
            .find(|r| r.name == name)
            .map(|r| r.id)
            .or_else(|| Abi::active().routed(name).map(|r| r.id))
            .unwrap_or_else(|| panic!("{name}"))
    }

    fn params(st: &str, fields: &[(&str, u64)]) -> Vec<u8> {
        let l = Abi::active().layout(st).unwrap();
        let mut b = vec![0u8; l.size];
        for &(f, x) in fields {
            let (o, n) = l.resolve(f).unwrap();
            b[o..o + n].copy_from_slice(&x.to_le_bytes()[..n]);
        }
        b
    }

    /// Compute mode (6.2) and GPU accounting (6.17): the legal values are recorded per VM,
    /// anything else is an invalid argument, and neither reaches the host.
    #[test]
    fn compute_mode_and_accounting_are_this_vms() {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut d = dispatcher(Some(Box::new(Rec(seen.clone()))));
        let cm = id("NV2080_CTRL_CMD_GPU_SET_COMPUTE_MODE_RULES");
        let p = params(
            "NV2080_CTRL_GPU_SET_COMPUTE_MODE_RULES_PARAMS",
            &[("rules", 2)],
        );
        let a = d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, cm, &p);
        assert_eq!((a.status, a.label), (0, COMPUTE_MODE));
        assert_eq!(d.dstate.compute_mode, 2);
        let p = params(
            "NV2080_CTRL_GPU_SET_COMPUTE_MODE_RULES_PARAMS",
            &[("rules", 7)],
        );
        let a = d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, cm, &p);
        assert_eq!(a.status, status("NV_ERR_INVALID_ARGUMENT"));
        assert_eq!(d.dstate.compute_mode, 2);
        let acct = id("NV0000_CTRL_CMD_GPUACCT_SET_ACCOUNTING_STATE");
        let st = "NV0000_CTRL_GPUACCT_SET_ACCOUNTING_STATE_PARAMS";
        let p = params(st, &[("gpuId", 0x500), ("newState", 0)]);
        let a = d.control(INTERNAL_CLIENT, INTERNAL_CLIENT, acct, &p);
        assert_eq!((a.status, a.label), (0, GPUACCT));
        assert_eq!(d.dstate.gpuacct.get(&0x500), Some(&0));
        let p = params(st, &[("gpuId", 0x500), ("newState", 9)]);
        let a = d.control(INTERNAL_CLIENT, INTERNAL_CLIENT, acct, &p);
        assert_eq!(a.status, status("NV_ERR_INVALID_ARGUMENT"));
        assert!(seen.lock().unwrap().is_empty());
    }

    /// The BAR0 map policy (6.4): deny by default; outside BAR0, straddling its end, empty,
    /// below it or wrapping is a protection fault too; an allow-list window maps.
    #[test]
    fn bar0_map_policy_denies_by_default() {
        let mut d = dispatcher(None);
        d.bar_offsets[0] = 0xE600_0000;
        let vm = id("NV2080_CTRL_CMD_GPU_VALIDATE_MEM_MAP_REQUEST");
        const P: &str = "NV2080_CTRL_GPU_VALIDATE_MEM_MAP_REQUEST_PARAMS";
        let fault = status("NV_ERR_PROTECTION_FAULT");
        let size = d.bar_sizes[0];
        for (start, len) in [
            (0xE600_0000 + 0x10_0000, 0x1000),
            (0xE600_0000 + size - 0x800, 0x1000),
            (0xE600_0000, 0),
            (0xE500_0000, 0x1000),
            (u64::MAX - 0x10, 0x1000),
            (0xE600_0000 + 0x10_0000, u64::MAX),
        ] {
            let p = params(P, &[("addressStart", start), ("addressLength", len)]);
            let a = d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, vm, &p);
            assert_eq!(
                (a.status, a.label),
                (fault, BAR0_POLICY),
                "{start:#x}+{len:#x}"
            );
        }
        d.dstate.bar0_allow.push((0x10_0000, 0x1000));
        let p = params(
            P,
            &[("addressStart", 0xE610_0000), ("addressLength", 0x1000)],
        );
        assert_eq!(
            d.control(INTERNAL_CLIENT, INTERNAL_SUBDEVICE, vm, &p)
                .status,
            0
        );
    }

    /// The debugger session's MMU debug mode (6.16): SET records per 83DE object, GET reads
    /// it back (DISABLED before any SET), another object is not affected.
    #[test]
    fn mmu_debug_mode_round_trip() {
        let mut d = dispatcher(None);
        let set = id("NV83DE_CTRL_CMD_DEBUG_SET_MODE_MMU_DEBUG");
        let get = id("NV83DE_CTRL_CMD_DEBUG_GET_MODE_MMU_DEBUG");
        let rd = |a: &Answer| u32::from_le_bytes(a.params[..4].try_into().unwrap());
        let a = d.control(0xC1, 0xDB, get, &[0u8; 4]);
        assert_eq!((a.status, rd(&a)), (0, 2));
        let a = d.control(0xC1, 0xDB, set, &1u32.to_le_bytes());
        assert_eq!((a.status, a.label), (0, DEBUGGER));
        assert_eq!(rd(&d.control(0xC1, 0xDB, get, &[0u8; 4])), 1);
        assert_eq!(rd(&d.control(0xC1, 0xDC, get, &[0u8; 4])), 2);
        let a = d.control(0xC1, 0xDB, set, &5u32.to_le_bytes());
        assert_eq!(a.status, status("NV_ERR_INVALID_ARGUMENT"));
        // A new object under the same handle starts disabled again.
        d.alloc(0xC1, 0xDB, 0xCAF0_0001, 0x83DE, &[0u8; 16]);
        assert_eq!(rd(&d.control(0xC1, 0xDB, get, &[0u8; 4])), 2);
    }

    /// ZBC through the dispatcher: a guest colour goes into this VM's table and comes back
    /// through GET_ZBC_CLEAR_TABLE_ENTRY; no host control is issued.
    #[test]
    fn zbc_through_the_dispatcher_stays_off_the_host() {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let mut d = dispatcher(Some(Box::new(Rec(seen.clone()))));
        let set = id("NV9096_CTRL_CMD_SET_ZBC_COLOR_CLEAR");
        let names: Vec<String> = (0..4).map(|i| format!("colorFB[{i}]")).collect();
        let mut f: Vec<(&str, u64)> = names.iter().map(|n| (n.as_str(), 0x0A0B_0C0D)).collect();
        f.push(("format", 0x28));
        let p = params("NV9096_CTRL_SET_ZBC_COLOR_CLEAR_PARAMS", &f);
        let a = d.control(0xC1, 0x9096, set, &p);
        assert_eq!((a.status, a.label), (0, crate::zbc::RECORDED));
        let get = id("NV9096_CTRL_CMD_GET_ZBC_CLEAR_TABLE_ENTRY");
        let st = "NV9096_CTRL_GET_ZBC_CLEAR_TABLE_ENTRY_PARAMS";
        let q = params(st, &[("tableType", 1), ("index", 4)]);
        let a = d.control(0xC1, 0x9096, get, &q);
        assert_eq!((a.status, a.label), (0, crate::zbc::READ));
        assert_eq!(&a.params[..4], &0x0A0B_0C0Du32.to_le_bytes());
        assert!(seen.lock().unwrap().is_empty());
    }

    /// The small recorders: FECS trace setters, FBSR_INIT, RATED_TDP; the flushes answer
    /// NV_OK without a host (no physical L2 behind the device).
    #[test]
    fn recorders_and_flush_without_a_host() {
        let mut d = dispatcher(None);
        let (c, s) = (INTERNAL_CLIENT, INTERNAL_SUBDEVICE);
        let p = params(
            "NV2080_CTRL_INTERNAL_GR_FECS_TRACE_HW_ENABLE_PARAMS",
            &[("bEnable", 1)],
        );
        d.control(
            c,
            s,
            id("NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_HW_ENABLE"),
            &p,
        );
        let p = params(
            "NV2080_CTRL_INTERNAL_GR_FECS_TRACE_OFFSET_PARAMS",
            &[("offset", 0x40)],
        );
        d.control(
            c,
            s,
            id("NV2080_CTRL_CMD_INTERNAL_GR_SET_FECS_TRACE_WR_OFFSET"),
            &p,
        );
        assert_eq!(d.dstate.fecs, (true, 0, 0x40));
        let p = params(
            "NV2080_CTRL_INTERNAL_FBSR_INIT_PARAMS",
            &[
                ("hClient", 0xC1),
                ("hSysMem", 0x77),
                ("sysmemAddrOfSuspendResumeData", 0x1000),
            ],
        );
        let a = d.control(c, s, id("NV2080_CTRL_CMD_INTERNAL_FBSR_INIT"), &p);
        assert_eq!((a.status, a.label), (0, SUSPEND));
        assert_eq!(d.dstate.fbsr, Some((0xC1, 0x77, false, 0x1000)));
        let p = params(
            "NV2080_CTRL_PERF_RATED_TDP_CONTROL_PARAMS",
            &[("client", 2), ("input", 1)],
        );
        let a = d.control(c, s, id("NV2080_CTRL_CMD_PERF_RATED_TDP_SET_CONTROL"), &p);
        assert_eq!((a.status, a.label), (0, RATED_TDP));
        assert_eq!(d.dstate.rated_tdp.get(&2), Some(&(1, 0)));
        let a = d.control(c, s, id("NV0080_CTRL_CMD_DMA_FLUSH"), &1u32.to_le_bytes());
        assert_eq!((a.status, a.label), (0, FLUSH));
        assert!(a.note.contains("no host RM"), "{}", a.note);
    }
}
